import React from 'react';
import './App.css';

const CustomLoader = () => {
  return (
    <div style={overlayStyle}>
      <div className="loader" />
    </div>
  );
};

const overlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100vw',
  height: '100vh',
  backgroundColor: 'rgba(255, 255, 255, 0.7)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  zIndex: 9999,
};

export default CustomLoader;
